import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.nn.modules.utils import _triple
from torch.utils.cpp_extension import load_inline


_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

__global__ __launch_bounds__(256) void conv_transpose3d_gather_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const long long total,
    const int N, const int C, const int D, const int H, const int W,
    const int OC, const int OD, const int OH, const int OW,
    const int KD, const int KH, const int KW,
    const int sd, const int sh, const int sw,
    const int pd, const int ph, const int pw,
    const int dd, const int dh, const int dw,
    const int groups,
    const bool has_bias)
{
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    long long t = idx;
    const int xo = (int)(t % OW); t /= OW;
    const int yo = (int)(t % OH); t /= OH;
    const int zo = (int)(t % OD); t /= OD;
    const int oc = (int)(t % OC); t /= OC;
    const int n  = (int)t;

    const int oc_per_g = OC / groups;
    const int c_per_g  = C / groups;
    const int g        = oc / oc_per_g;
    const int oc_g     = oc - g * oc_per_g;
    const int c0       = g * c_per_g;
    const int c1       = c0 + c_per_g;

    float acc = has_bias ? b[oc] : 0.0f;

    for (int c = c0; c < c1; ++c) {
        const long long x_base_c = (((long long)n * C + c) * D) * H * W;
        const long long w_base_c = (((long long)c * oc_per_g + oc_g) * KD) * KH * KW;
        for (int kz = 0; kz < KD; ++kz) {
            const int znum = zo + pd - kz * dd;
            if (znum < 0 || (znum % sd) != 0) continue;
            const int zi = znum / sd;
            if (zi < 0 || zi >= D) continue;

            for (int ky = 0; ky < KH; ++ky) {
                const int ynum = yo + ph - ky * dh;
                if (ynum < 0 || (ynum % sh) != 0) continue;
                const int yi = ynum / sh;
                if (yi < 0 || yi >= H) continue;

                for (int kx = 0; kx < KW; ++kx) {
                    const int xnum = xo + pw - kx * dw;
                    if (xnum < 0 || (xnum % sw) != 0) continue;
                    const int xi = xnum / sw;
                    if (xi < 0 || xi >= W) continue;

                    const long long x_idx = x_base_c + ((long long)zi * H + yi) * W + xi;
                    const long long w_idx = w_base_c + ((long long)kz * KH + ky) * KW + kx;
                    acc += x[x_idx] * w[w_idx];
                }
            }
        }
    }

    y[idx] = acc;
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be NCDHW");
    TORCH_CHECK(weight.dim() == 5, "weight must be (C, OC/groups, KD, KH, KW)");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias.numel() == weight.size(1) * groups, "bias has wrong size");
    }

    const int64_t N = x.size(0);
    const int64_t C = x.size(1);
    const int64_t D = x.size(2);
    const int64_t H = x.size(3);
    const int64_t W = x.size(4);

    const int64_t WC = weight.size(0);
    const int64_t KD = weight.size(2);
    const int64_t KH = weight.size(3);
    const int64_t KW = weight.size(4);
    const int64_t OC = weight.size(1) * groups;

    TORCH_CHECK(WC == C, "weight in_channels mismatch");
    TORCH_CHECK(C % groups == 0, "in_channels must be divisible by groups");
    TORCH_CHECK(OC % groups == 0, "out_channels must be divisible by groups");

    const int64_t OD = (D - 1) * stride_d - 2 * pad_d + dil_d * (KD - 1) + out_pad_d + 1;
    const int64_t OH = (H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + out_pad_h + 1;
    const int64_t OW = (W - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + out_pad_w + 1;
    TORCH_CHECK(OD > 0 && OH > 0 && OW > 0, "invalid output size");

    auto y = at::empty({N, OC, OD, OH, OW}, x.options());
    const long long total = (long long)N * OC * OD * OH * OW;
    if (total == 0) return y;

    const float* x_ptr = x.data_ptr<float>();
    const float* w_ptr = weight.data_ptr<float>();
    const float* b_ptr = has_bias ? bias.data_ptr<float>() : nullptr;
    float* y_ptr = y.data_ptr<float>();

    const int threads = 256;
    const long long blocks_ll = (total + threads - 1) / threads;
    TORCH_CHECK(blocks_ll <= 2147483647LL, "too many blocks");
    const dim3 blocks((unsigned int)blocks_ll);
    const dim3 threads_dim(threads);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv_transpose3d_gather_kernel<<<blocks, threads_dim, 0, stream>>>(
        x_ptr, w_ptr, b_ptr, y_ptr,
        total,
        (int)N, (int)C, (int)D, (int)H, (int)W,
        (int)OC, (int)OD, (int)OH, (int)OW,
        (int)KD, (int)KH, (int)KW,
        (int)stride_d, (int)stride_h, (int)stride_w,
        (int)pad_d, (int)pad_h, (int)pad_w,
        (int)dil_d, (int)dil_h, (int)dil_w,
        (int)groups,
        has_bias);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_mod = load_inline(
    name="custom_conv_transpose3d_gather",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose3d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, output_padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        k = _triple(kernel_size)
        s = _triple(stride)
        p = _triple(padding)
        op = _triple(output_padding)
        d = _triple(dilation)

        if in_channels % groups != 0:
            raise ValueError("in_channels must be divisible by groups")
        if out_channels % groups != 0:
            raise ValueError("out_channels must be divisible by groups")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = k
        self.stride = s
        self.padding = p
        self.output_padding = op
        self.dilation = d
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, k[0], k[1], k[2]))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        if self.bias is None:
            b = torch.empty(0, device=x.device, dtype=x.dtype)
            has_bias = False
        else:
            b = self.bias
            has_bias = True
        return _mod.conv_transpose3d_forward(
            x, self.weight, b, has_bias,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.dilation[0], self.dilation[1], self.dilation[2],
            self.groups
        )

